<script setup lang="ts">
import{onMounted,ref}from'vue';import{request}from'../api/request';import{useRoute}from'vue-router';import{ElMessage}from'element-plus';import{useAuthStore}from'../stores/auth'
const route=useRoute(),auth=useAuthStore(),d=ref<any>(),trace=ref<any[]>([]),busy=ref(false)
async function load(){d.value=await request.get('/api/ai/diagnoses/'+route.params.id);trace.value=await request.get('/api/ai/diagnoses/'+route.params.id+'/workflow')}
async function confirm(ok:boolean){busy.value=true;try{await request.post('/api/ai/diagnoses/'+route.params.id+(ok?'/confirm':'/reject'),{comment:''});ElMessage.success(ok?'已确认':'已拒绝');load()}finally{busy.value=false}}
onMounted(load)
</script><template><section><h1>AI 诊断详情</h1><el-card v-loading="!d"><el-descriptions v-if="d?.diagnosis" :column="2" border><el-descriptions-item label="风险等级">{{d.diagnosis.riskLevel}}</el-descriptions-item><el-descriptions-item label="异常摘要">{{d.diagnosis.abnormalSummary}}</el-descriptions-item><el-descriptions-item label="维修建议">{{d.diagnosis.maintenanceAdvice}}</el-descriptions-item><el-descriptions-item label="安全提示">{{d.diagnosis.safetyNotice}}</el-descriptions-item><el-descriptions-item label="人工确认">{{d.humanConfirmationRequired}}</el-descriptions-item></el-descriptions><h3>可能原因</h3><el-tag v-for="x in d?.possibleCauses" :key="x">{{x}}</el-tag><h3>排查步骤</h3><ol><li v-for="x in d?.investigationSteps" :key="x">{{x}}</li></ol><h3>工单草案（不会自动创建）</h3><pre>{{d?.workOrderDraft}}</pre><el-button v-if="auth.can('ai:confirm')" type="primary" :loading="busy" @click="confirm(true)">确认</el-button><el-button v-if="auth.can('ai:confirm')" :loading="busy" @click="confirm(false)">拒绝</el-button><h3>五节点 Workflow Trace</h3><el-steps><el-step v-for="x in trace" :key="x.id" :title="x.nodeCode" :description="x.nodeStatus"/></el-steps></el-card></section></template>
